export const CAD_TYPES=['line','rectangle','circle','polygon','box','cylinder','sphere','extrusion','mesh','pipe'];
export const CAD_STYLES=['textured','monochrome','wireframe','xray'];
export const cadId=()=>globalThis.crypto.randomUUID();
export const finite=(v,min=-1000,max=1000)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;
const text=(s,n=100)=>typeof s==='string'&&s.length>0&&s.length<=n;
const color=s=>typeof s==='string'&&/^#[0-9a-f]{6}$/i.test(s);
export const area2=pts=>pts.reduce((sum,p,i)=>{const q=pts[(i+1)%pts.length];return sum+p[0]*q[1]-q[0]*p[1];},0)/2;
const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
function onSegment(a,b,p){return Math.abs(cross(a,b,p))<1e-8&&p[0]>=Math.min(a[0],b[0])-1e-8&&p[0]<=Math.max(a[0],b[0])+1e-8&&p[1]>=Math.min(a[1],b[1])-1e-8&&p[1]<=Math.max(a[1],b[1])+1e-8;}
function intersects(a,b,c,d){return cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0||onSegment(a,b,c)||onSegment(a,b,d)||onSegment(c,d,a)||onSegment(c,d,b);}
export function validateProfile(points){if(!Array.isArray(points)||points.length<3||points.length>256||points.some(p=>!Array.isArray(p)||p.length!==2||!p.every(v=>finite(v,-200,200))))throw Error('A profile needs 3–256 finite X,Z points.');for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if(Math.hypot(b[0]-a[0],b[1]-a[1])<.001)throw Error('Profile edges must be at least 1 mm long.');for(let j=i+1;j<points.length;j++){if(j===i+1||i===0&&j===points.length-1)continue;if(intersects(a,b,points[j],points[(j+1)%points.length]))throw Error('The profile crosses or touches itself.');}}if(Math.abs(area2(points))<.000001)throw Error('Profile area is too small.');return points;}
export function offsetProfile(points,distance){validateProfile(points);if(!finite(distance,-20,20)||Math.abs(distance)<.0001)throw Error('Enter a nonzero offset up to 20 m.');const sign=Math.sign(area2(points));const lines=points.map((p,i)=>{const q=points[(i+1)%points.length],dx=q[0]-p[0],dz=q[1]-p[1],L=Math.hypot(dx,dz);return{p:[p[0]+sign*dz/L*distance,p[1]-sign*dx/L*distance],v:[dx,dz]};});const result=points.map((_,i)=>{const a=lines[(i+lines.length-1)%lines.length],b=lines[i],den=a.v[0]*b.v[1]-a.v[1]*b.v[0];if(Math.abs(den)<1e-9)throw Error('Remove collinear corners before offsetting.');const dx=b.p[0]-a.p[0],dz=b.p[1]-a.p[1],t=(dx*b.v[1]-dz*b.v[0])/den;return[a.p[0]+t*a.v[0],a.p[1]+t*a.v[1]];});validateProfile(result);if(Math.sign(area2(result))!==sign)throw Error('This offset collapses the profile.');for(let i=0;i<points.length;i++){const q=(i+1)%points.length;if((result[q][0]-result[i][0])*(points[q][0]-points[i][0])+(result[q][1]-result[i][1])*(points[q][1]-points[i][1])<=0)throw Error('This offset collapses an edge.');}return result;}
export function newCAD(){return{schema:1,entities:[],definitions:[],groups:[],tags:[{id:'untagged',name:'Untagged',color:'#b9a0ff',visible:true}],scenes:[],view:{style:'textured',projection:'perspective',section:{enabled:false,axis:'y',offset:1.5}}};}
export function ensureCAD(project){return project.cad??=newCAD();}
export function newEntity(type,floorId,params={},position=[0,0,0]){if(!CAD_TYPES.includes(type))throw Error('Unsupported model type.');return{id:cadId(),name:type[0].toUpperCase()+type.slice(1),floorId,tagId:'untagged',visible:true,locked:false,color:'#b8c4ad',position,rotation:[0,0,0],scale:[1,1,1],shape:{type,params}};}
export function resolveShape(cad,entity){return entity.definitionId?cad.definitions.find(d=>d.id===entity.definitionId)?.shape:entity.shape;}
export function profileFor(shape){const p=shape.params;if(shape.type==='box'||shape.type==='rectangle')return[[-p.width/2,-p.depth/2],[p.width/2,-p.depth/2],[p.width/2,p.depth/2],[-p.width/2,p.depth/2]];if(['circle','cylinder'].includes(shape.type))return Array.from({length:p.segments||32},(_,i)=>{const a=i*Math.PI*2/(p.segments||32);return[Math.cos(a)*p.radius,Math.sin(a)*p.radius];});if(['polygon','extrusion'].includes(shape.type))return p.points;throw Error('Select a rectangle, circle, or polygon profile.');}
function shapeValid(s){if(!s||!CAD_TYPES.includes(s.type)||!s.params||typeof s.params!=='object')throw Error('Invalid model shape.');const p=s.params,pos=(v)=>finite(v,.001,200);if(['box','rectangle'].includes(s.type)&&(!pos(p.width)||!pos(p.depth)))throw Error('Width and depth must be between 1 mm and 200 m.');if(['box','cylinder'].includes(s.type)&&!pos(p.height))throw Error('Height must be positive.');if(['circle','cylinder','sphere','pipe'].includes(s.type)&&!pos(p.radius))throw Error('Radius must be positive.');if(p.segments!==undefined&&(!Number.isInteger(p.segments)||p.segments<8||p.segments>96))throw Error('Use 8–96 curve segments.');if(['polygon','extrusion'].includes(s.type))validateProfile(p.points);if(s.type==='extrusion'&&(!finite(p.height,-200,200)||Math.abs(p.height)<.001))throw Error('Extrusion must be at least 1 mm.');if(['line','pipe'].includes(s.type)&&(!Array.isArray(p.points)||p.points.length<2||p.points.length>256||p.points.some(a=>!Array.isArray(a)||a.length!==3||!a.every(v=>finite(v,-200,200)))))throw Error('A path needs 2–256 XYZ points.');if(['line','pipe'].includes(s.type))for(let i=1;i<p.points.length;i++)if(Math.hypot(...p.points[i].map((v,k)=>v-p.points[i-1][k]))<.001)throw Error('Path segments must be at least 1 mm.');if(s.type==='mesh'){if(!Array.isArray(p.vertices)||p.vertices.length<9||p.vertices.length>300000||p.vertices.length%9||!p.vertices.every(v=>finite(v,-1000,1000)))throw Error('Mesh must contain at most 100,000 triangle vertices within a 1 km local extent.');}return s;}
export function validateCAD(cad,floorIds,used=new Set()){if(!cad||cad.schema!==1||!Array.isArray(cad.entities)||cad.entities.length>2000||!Array.isArray(cad.definitions)||cad.definitions.length>500||!Array.isArray(cad.tags)||!cad.tags.length||cad.tags.length>200||!Array.isArray(cad.groups)||cad.groups.length>500||!Array.isArray(cad.scenes)||cad.scenes.length>100)throw Error('Invalid or oversized modeling document.');const id=o=>{if(typeof o.id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(o.id)||used.has(o.id))throw Error('Duplicate or invalid model ID.');used.add(o.id);};for(const tag of cad.tags){id(tag);if(!text(tag.name)||!color(tag.color)||typeof tag.visible!=='boolean')throw Error('Invalid tag.');}if(!cad.tags.some(t=>t.id==='untagged'))throw Error('Untagged tag is required.');for(const def of cad.definitions){id(def);if(!text(def.name))throw Error('Invalid component name.');shapeValid(def.shape);}for(const group of cad.groups){id(group);if(!text(group.name))throw Error('Invalid group name.');}for(const e of cad.entities){id(e);if(!text(e.name)||!floorIds.includes(e.floorId)||!cad.tags.some(t=>t.id===e.tagId)||!color(e.color)||typeof e.visible!=='boolean'||typeof e.locked!=='boolean')throw Error('Invalid model properties or floor.');for(const key of ['position','rotation','scale'])if(!Array.isArray(e[key])||e[key].length!==3||!e[key].every(v=>finite(v,key==='rotation'?-36000:key==='scale'?-1000:-1000,key==='rotation'?36000:1000))||key==='scale'&&e[key].some(v=>Math.abs(v)<.001))throw Error('Invalid model transform.');if(e.groupId&&!cad.groups.some(g=>g.id===e.groupId))throw Error('Unknown model group.');if(e.definitionId){if(!cad.definitions.some(d=>d.id===e.definitionId))throw Error('Unknown component definition.');}else shapeValid(e.shape);}
const viewValid=v=>{if(!v||!CAD_STYLES.includes(v.style)||!['perspective','parallel'].includes(v.projection)||!v.section||typeof v.section.enabled!=='boolean'||!['x','y','z'].includes(v.section.axis)||!finite(v.section.offset,-1000,1000))throw Error('Invalid view settings.');};viewValid(cad.view);for(const scene of cad.scenes){id(scene);if(!text(scene.name)||!floorIds.includes(scene.floorId)||!Array.isArray(scene.position)||!Array.isArray(scene.target)||scene.position.length!==3||scene.target.length!==3||![...scene.position,...scene.target].every(v=>finite(v,-10000,10000)))throw Error('Invalid saved scene.');if(scene.up!==undefined&&(!Array.isArray(scene.up)||scene.up.length!==3||!scene.up.every(v=>finite(v,-1,1))||Math.hypot(...scene.up)<.001))throw Error('Invalid saved camera orientation.');viewValid(scene.view);}return cad;}
export function makeComponent(cad,entity,name){const shape=structuredClone(resolveShape(cad,entity)),definition={id:cadId(),name,shape};cad.definitions.push(definition);entity.definitionId=definition.id;delete entity.shape;return definition;}
export function makeUnique(cad,entity){if(!entity.definitionId)return;entity.shape=structuredClone(resolveShape(cad,entity));delete entity.definitionId;}
export function duplicateEntity(entity){const copy=structuredClone(entity);copy.id=cadId();copy.name+=' copy';copy.position[0]+=.4;delete copy.groupId;return copy;}
export function groupEntities(cad,ids,name='Model group'){const entities=cad.entities.filter(e=>ids.includes(e.id));if(entities.length<2||entities.some(e=>e.locked))throw Error('Select at least two unlocked models to group.');const g={id:cadId(),name};cad.groups.push(g);for(const e of entities)e.groupId=g.id;cad.groups=cad.groups.filter(gr=>cad.entities.some(e=>e.groupId===gr.id));return g;}
export function snapPoint(point,points=[],step=.1,threshold=.15,axisOrigin=null){let result=[Math.round(point[0]/step)*step,Math.round(point[1]/step)*step],kind='grid',best=threshold;for(const p of points){const d=Math.hypot(p[0]-point[0],p[1]-point[1]);if(d<best){result=[...p];best=d;kind='endpoint';}}if(kind==='grid'&&axisOrigin){if(Math.abs(point[0]-axisOrigin[0])<threshold){result[0]=axisOrigin[0];kind='axis';}else if(Math.abs(point[1]-axisOrigin[1])<threshold){result[1]=axisOrigin[1];kind='axis';}}return{point:result,kind};}
